<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {locale,t} from '../i18n'
import {path} from '../data'
import snapshots from '../news-locales.json'
import digests from '../news-digests.json'
import assetSources from '../../asset-sources.json'
import sources from '../news-sources.json'
const route=useRoute(),router=useRouter(),category=ref('All'),limit=ref(10)
const all=computed(()=>snapshots[locale.value]||snapshots['en-US']),aliases={google:1,ethereum:2,cftc:3,binance:4}
const selectedImage=computed(()=>{for(const list of Object.values(snapshots)){const found=list.find(n=>n.id===route.params.id);if(found)return found.image}return snapshots['en-US'][aliases[route.params.id]]?.image})
const article=computed(()=>all.value.find(n=>n.image===selectedImage.value)),source=computed(()=>sources.find(n=>n.image===article.value?.image))
const digest=computed(()=>digests[sources.findIndex(n=>n.image===article.value?.image)]?.[locale.value]||'')
const filtered=computed(()=>all.value.filter(n=>category.value==='All'||n.meta.includes(category.value))),visible=computed(()=>filtered.value.slice(0,limit.value))
watch(category,()=>limit.value=10)
watch(locale,()=>{if(article.value&&route.params.id!==article.value.id)router.replace(path('/news/'+article.value.id))})
function imageFor(n){return assetSources[n.image]?'/newtrend/assets/'+assetSources[n.image]:null}
</script>
<template><template v-if="!route.params.id"><header class="news-heading grid-background"><nav><RouterLink :to="path('/')">{{t('news.breadcrumbHome')}}</RouterLink><span>/</span>{{t('news.breadcrumbNews')}}</nav><h1>{{t('news.pageTitle')}}</h1></header><section class="news-feed"><div class="news-filters"><button v-for="c in ['All','Market Updates','Crypto','Macro','Platform Announcements']" :class="{active:category===c}" :aria-pressed="category===c" @click="category=c">{{c==='All'?t('news.categoryAll'):c}}</button></div><RouterLink v-for="n in visible" :key="n.id" class="news-item" :to="path('/news/'+n.id)"><img v-if="imageFor(n)" :src="imageFor(n)" alt="" loading="lazy"/><div v-else class="news-image-slot" aria-hidden="true"></div><div><small>{{n.meta}}</small><h3>{{n.title}}</h3><p>{{n.summary}}</p><div class="news-tags"><span v-for="tag in n.tags.filter(tag=>!['Market Updates','Crypto','Macro','Platform Announcements'].includes(tag))">{{tag}}</span></div><span class="sr-only">{{t('news.readTime',{minutes:3})}}</span></div></RouterLink><div v-if="!visible.length" class="empty"><h2>{{t('news.emptyTitle')}}</h2><p>{{t('news.emptyHint')}}</p></div><button v-if="limit<filtered.length" class="secondary-button load-more" @click="limit+=10">{{t('news.loadMore')}}</button><p v-else-if="visible.length" class="mini-label center">{{t('news.noMore')}}</p></section></template><template v-else-if="article"><header class="news-heading article-heading"><nav><RouterLink :to="path('/')">{{t('news.breadcrumbHome')}}</RouterLink><span>/</span><RouterLink :to="path('/news')">{{t('news.breadcrumbNews')}}</RouterLink><span>/</span><span>{{article.title}}</span></nav><h1>{{article.title}}</h1><p class="article-meta"><span>CoinTeleGraph</span><span>{{t('news.publishedAt')}} {{article.meta.split('·')[1]}}</span></p></header><article class="article-content"><p class="article-lead">{{article.summary}}</p><p class="article-body">{{digest}}</p><div class="article-links"><a class="green-link" :href="source?.url" target="_blank" rel="noopener">{{t('news.viewOriginal')}}</a><a href="https://cointelegraph.com/" class="muted" target="_blank" rel="noopener">{{t('news.viewSource')}}</a></div><RouterLink :to="path('/news')" class="green-link">{{t('news.backToList')}}</RouterLink></article></template><section v-else class="empty news-missing"><h1>{{t('news.articleNotFound')}}</h1><RouterLink class="primary-button" :to="path('/news')">{{t('news.backToList')}}</RouterLink></section></template>
<style scoped>.news-heading{padding:96px 24px;border-bottom:1px solid #ffffff12}.news-heading>*{max-width:1352px;margin-left:auto;margin-right:auto}.news-heading nav>span{min-width:0;overflow-wrap:anywhere}.news-heading nav{display:flex;gap:12px;flex-wrap:wrap;color:#fff9;font:12px/16px 'IBM Plex Mono',monospace;margin-bottom:24px}.news-heading h1{overflow-wrap:anywhere;font-size:3rem;line-height:1;letter-spacing:-1px}.grid-background{background:radial-gradient(ellipse at 50% 0,#bdff0006,transparent 70%),linear-gradient(90deg,#ffffff08 1px,transparent 1px),linear-gradient(#ffffff08 1px,transparent 1px);background-size:auto,56px 56px,56px 56px}.news-feed{max-width:1400px;margin:auto;padding:32px 24px 64px}.news-filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:64px}.news-filters button{padding:6px 16px;line-height:20px;border:1px solid #ffffff12;border-radius:99px;font-size:0.875rem}.news-filters .active{background:#c2ff0012;color:var(--nt-accent);border-color:#c2ff0040}.news-item{display:flex;gap:24px;padding:24px;margin-bottom:24px;border:1px solid transparent;border-radius:4px}.news-item:hover{background:#ffffff03;border-color:#c2ff0020}.news-item img,.news-image-slot{width:176px;height:112px;object-fit:cover;border-radius:2px;flex-shrink:0}.news-item>div{min-width:0}.news-item small{display:block;line-height:16px}.news-item small,.article-meta{color:#fff9;font:12px/16px 'IBM Plex Mono',monospace}.news-item h3{font-size:1.25rem;margin:8px 0;line-height:1.375}.news-item:hover h3{color:var(--nt-accent)}.news-item p{font-size:0.875rem;line-height:20px;color:#fff9}.news-tags{display:flex;gap:8px;margin-top:12px}.news-tags span{font:12px/16px monospace;border:1px solid #ffffff12;border-radius:4px;padding:2px 8px;color:#fff9}.load-more{display:block;margin:32px auto}.center{text-align:center}.article-heading nav{margin-bottom:32px}.article-heading h1{line-height:1.25}.article-meta{display:flex;gap:16px;flex-wrap:wrap;margin-top:24px}.article-content{padding:64px 24px;max-width:1400px;margin:auto}.article-content>*{max-width:calc((100% - 24px)*2/3)}.article-lead{font-size:1.125rem;color:#fff9;line-height:1.8;margin-bottom:32px}.article-body{font-size:1rem;line-height:1.8;color:#fffb;white-space:pre-line}.article-links{display:flex;gap:24px;margin:32px 0 48px}.news-missing{min-height:60vh}@media(max-width:700px){.news-heading{padding:48px 20px}.news-heading h1{overflow-wrap:anywhere;font-size:2rem}.news-heading>*{max-width:1352px;margin-left:auto;margin-right:auto}.news-heading nav>span{min-width:0;overflow-wrap:anywhere}.news-heading nav{margin-bottom:24px}.news-feed{padding:24px 16px 48px}.news-filters{margin-bottom:32px}.news-item{padding:16px 4px;gap:16px}.news-item img,.news-image-slot{display:none}.news-item h3{font-size:1.125rem}.article-content{padding:40px 20px}.article-content>*{max-width:100%}.article-lead{font-size:1rem}}
</style>
